import { Group, Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const root = new Group();

  // --- Plane ---
  const planeGeom = new PlaneGeometry(7, 3, 1, 1); // size placeholder; can be adjusted via scale if needed
  const planeMat = new MeshBasicNodeMaterial({ color: 0xffffff });
  const planeMesh = new Mesh(planeGeom, planeMat);
  root.add(planeMesh);

  // Load texture (if provided)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // --- Text ---
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 42,
      color: config.visual?.colors?.paper ?? '#e8ecf2',
      align: 'left',
    });
    // Position text slightly above the plane surface
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // Apply rotation and scale from config (position is handled by adapter)
  if (config.rotation) {
    root.rotation.set(
      config.rotation[0] ?? 0,
      config.rotation[1] ?? 0,
      config.rotation[2] ?? 0
    );
  }

  if (config.scale) {
    root.scale.set(
      config.scale[0] ?? 1,
      config.scale[1] ?? 1,
      config.scale[2] ?? 1
    );
  }

  // Handlers placeholder (no interactions specified)
  root.userData.handlers = {};

  // Cleanup
  root.userData.cleanup = () => {
    // Dispose geometry and material
    planeGeom.dispose();
    if (planeMat.map) planeMat.map.dispose();
    planeMat.dispose();

    // Dispose any text objects (they manage their own resources)
    if (root.children) {
      for (const child of root.children) {
        if (child.geometry) child.geometry.dispose?.();
        if (child.material) child.material.dispose?.();
      }
    }

    // Kill any GSAP timelines (none created here but safe)
    gsap.globalTimeline.clear();
  };

  return root;
}
